local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local PluginsManager = require(script.Parent.shared.PluginsManager)

local TangSengDebugger = {}
TangSengDebugger.__index = TangSengDebugger

function TangSengDebugger.new(
	env: IHostingEnvironment,
	plugins: IEnumerable<ITangSengDebuggerPluginsProvider>,
	options: ITangSengDebuggerOptions
)
	local self = setmetatable({}, TangSengDebugger)

	-- plugins
	for k, v in plugins do
		PluginsManager.AddSystems(v.Systems)
		PluginsManager.AddComponents(v.Components)
	end

	-- debugger
	local components = require(script.Parent.shared.components)
	local ts = require(script.Parent.Parent)
	local debugger

	if env.IsServer() then
		debugger = require(script.Parent.server.serverInit)(components, ts.GetServices(), ts.GetFacadeOfPlayer)
	else
		debugger = require(script.Parent.client.clientInit)(components, ts.GetServices(), ts.GetFacadeOfPlayer)
	end

	-- auth
	debugger.authorize = options.Authorizor

	-- key code
	if RunService:IsClient() then
		UserInputService.InputBegan:Connect(function(input)
			if input.KeyCode == options.KeyCode then
				debugger:toggle()
			end
		end)
	end
	return debugger
end

return TangSengDebugger
